67	// ─── sendMessageAction ────────────────────────────────────────────────────────
68	
69	const SendMessageSchema = z.object({
70	  conversationId: z.string().uuid(),
71	  clientId: z.string().uuid(),
72	  body: z.string().min(1).max(1600),
73	  channel: z.enum(['sms', 'email']),
74	  subject: z.string().max(200).optional(),
75	})
76	
77	export async function sendMessageAction(
78	  input: z.infer<typeof SendMessageSchema>,
79	): Promise<ActionResult<{ commId: string }>> {
80	  const authUser = await getAuthenticatedUser()
81	  if (!authUser) return { ok: false, error: 'Unauthorized' }
82	
83	  const parsed = SendMessageSchema.safeParse(input)
84	  if (!parsed.success) {
85	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
86	  }
87	
88	  const { conversationId, clientId, body, channel, subject } = parsed.data
89	  const { studioId } = authUser
90	
91	  try {
92	    if (channel === 'sms') {
93	      const result = await sendSmsToClient(
94	        { studioId, clientId, body },
95	        authUser.user.id,
96	      )
97	      if (!result.ok) {
98	        return { ok: false, error: result.error ?? 'Failed to send SMS' }
99	      }
100	      revalidateMessages()
101	      return { ok: true, data: { commId: result.commId ?? '' } }
102	    }
103	
104	    if (channel === 'email') {
105	      const result = await sendEmailToClient(
106	        {
107	          studioId,
108	          clientId,
109	          subject: subject ?? '(no subject)',
110	          body,
111	        },
112	        authUser.user.id,
113	      )
114	      if (!result.ok) {
115	        return { ok: false, error: result.error ?? 'Failed to send email' }
116	      }
117	      revalidateMessages()
118	      return { ok: true, data: { commId: result.commId ?? '' } }
119	    }
120	
121	    return { ok: false, error: 'Unsupported channel' }
122	  } catch (err) {
123	    logger.error({ err, conversationId }, 'sendMessageAction: unexpected error')
124	    return { ok: false, error: 'Failed to send message' }
125	  }
126	}
