276	// ─── fireSmartReplyAction ─────────────────────────────────────────────────────
277	
278	const FireSmartReplySchema = z.object({
279	  conversationId: z.string().uuid(),
280	  action: z.discriminatedUnion('kind', [
281	    z.object({ kind: z.literal('send_template'), templateSlug: z.string().min(1) }),
282	    z.object({ kind: z.literal('open_calendar_reschedule'), bookingId: z.string().uuid() }),
283	    z.object({ kind: z.literal('share_portfolio') }),
284	    z.object({ kind: z.literal('offer_slots'), days: z.union([z.literal(1), z.literal(3), z.literal(7)]) }),
285	    z.object({ kind: z.literal('send_aftercare_pdf') }),
286	    z.object({ kind: z.literal('request_deposit') }),
287	  ]),
288	  clientId: z.string().uuid(),
289	  channel: z.enum(['sms', 'email']).default('sms'),
290	})
291	
292	export async function fireSmartReplyAction(
293	  input: z.infer<typeof FireSmartReplySchema>,
294	): Promise<ActionResult<{ commId?: string | undefined; navigateTo?: string | undefined }>> {
295	  const authUser = await getAuthenticatedUser()
296	  if (!authUser) return { ok: false, error: 'Unauthorized' }
297	
298	  const parsed = FireSmartReplySchema.safeParse(input)
299	  if (!parsed.success) {
300	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
301	  }
302	
303	  const { conversationId, action, clientId, channel } = parsed.data
304	  const { studioId } = authUser
305	
306	  try {
307	    // Navigation actions — return route for client-side navigation
308	    if (action.kind === 'open_calendar_reschedule') {
309	      return {
310	        ok: true,
311	        data: { navigateTo: `/calendar?rescheduleBooking=${action.bookingId}` },
312	      }
313	    }
314	
315	    // Slot-offer action — render placeholder from template
316	    if (action.kind === 'offer_slots') {
317	      const templates = await listMessageTemplates(studioId, { category: 'reschedule' })
318	      const tpl = templates[0]
319	      if (!tpl) {
320	        return { ok: false, error: 'Reschedule template not found. Add one in Settings → Messaging.' }
321	      }
322	      const result = await sendSmsToClient(
323	        { studioId, clientId, body: tpl.body },
324	        authUser.user.id,
325	      )
326	      if (!result.ok) return { ok: false, error: result.error }
327	      revalidateMessages()
328	      return { ok: true, data: { commId: result.commId } }
329	    }
330	
331	    // Template-based actions — map slug to send
332	    let templateSlug: string | null = null
333	
334	    if (action.kind === 'send_template') {
335	      templateSlug = action.templateSlug
336	    } else if (action.kind === 'send_aftercare_pdf') {
337	      templateSlug = 'aftercare-guide'
338	    } else if (action.kind === 'request_deposit') {
339	      templateSlug = 'deposit-request'
340	    } else if (action.kind === 'share_portfolio') {
341	      templateSlug = 'portfolio-share'
342	    }
343	
344	    if (!templateSlug) {
345	      return { ok: false, error: 'Unknown smart reply action' }
346	    }
347	
348	    const templates = await listMessageTemplates(studioId)
349	    const tpl = templates.find((t) => t.slug === templateSlug)
350	
351	    if (!tpl) {
352	      return { ok: false, error: `Template '${templateSlug}' not found. Check Settings → Messaging.` }
353	    }
354	
355	    let result: Awaited<ReturnType<typeof sendSmsToClient>>
356	
357	    if (channel === 'email') {
358	      result = await sendEmailToClient(
359	        { studioId, clientId, subject: tpl.name, body: tpl.body },
360	        authUser.user.id,
361	      )
362	    } else {
363	      result = await sendSmsToClient(
364	        { studioId, clientId, body: tpl.body },
365	        authUser.user.id,
366	      )
367	    }
368	
369	    if (!result.ok) return { ok: false, error: result.error }
370	
371	    revalidateMessages()
372	    return { ok: true, data: { commId: result.commId } }
373	  } catch (err) {
374	    logger.error({ err, conversationId }, 'fireSmartReplyAction: unexpected error')
375	    return { ok: false, error: 'Failed to send smart reply' }
376	  }
377	}
