export async function seedDefaultTemplatesAction(): Promise<ActionResult<{ inserted: number }>> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }
  const gateErr = await requireOmnichannelGate(authUser.studioId)
  if (gateErr) return gateErr

  try {
    const supabase = await createClient()
    const { data: member } = await supabase
      .from('studio_members')
      .select('role')
      .eq('studio_id', authUser.studioId)
      .eq('user_id', authUser.user.id)
      .is('deactivated_at', null)
      .single()
    if (!member || !['owner', 'admin'].includes(member.role)) {
      return { ok: false, error: 'Only owners and admins can restore defaults' }
    }
    const inserted = await seedDefaultTemplates(authUser.studioId, authUser.user.id, supabase)
    revalidateMessages()
    return { ok: true, data: { inserted } }
  } catch (err) {
    logger.error({ err }, 'seedDefaultTemplatesAction: failed')
    return { ok: false, error: 'Failed to seed default templates' }
  }
}

